/**
 * Unicode character-classification primitives that CPython relies on.
 *
 * Only the three questions the port actually asks are answered here:
 *   - is this code point whitespace for `int()`'s leading/trailing strip?
 *   - is this code point printable for `repr()`?
 *   - if it is a decimal digit, what is its numeric value?
 *
 * Every rule below was pinned against the reference build rather than guessed,
 * because CPython's notion of "whitespace" and "printable" both differ from
 * JavaScript's built-in `\s` and from each other.
 */

/**
 * Code points stripped by `int(str)`.
 *
 * This is CPython's `Py_UNICODE_ISSPACE` as observed through `int()`, and it is
 * deliberately *not* JavaScript's `\s`:
 *   - U+FEFF and U+200B are `\s`-adjacent but are rejected by `int()`.
 *   - U+0085 and U+000B are accepted by `int()`.
 *   - U+001C..U+001F are rejected, even though `str.isspace()` accepts them.
 */
const INT_WHITESPACE = new Set([
  0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x20, // \t \n \v \f \r and space
  0x85, 0xa0, // NEL, NBSP
  0x1680, // OGHAM SPACE MARK
  0x2000, 0x2001, 0x2002, 0x2003, 0x2004, 0x2005,
  0x2006, 0x2007, 0x2008, 0x2009, 0x200a,
  0x2028, 0x2029, // LINE / PARAGRAPH SEPARATOR
  0x202f, 0x205f, 0x3000,
]);

/** True when `int()` would strip this code point as surrounding whitespace. */
export function isIntWhitespace(codePoint) {
  return INT_WHITESPACE.has(codePoint);
}

/**
 * Categories CPython treats as non-printable in `repr()`: the Other groups
 * (Cc, Cf, Cs, Co, Cn) plus the Separator groups (Zl, Zp, Zs).
 *
 * U+0020 is the single exception — it is Zs yet prints raw.
 */
const NON_PRINTABLE = /[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]/u;

const SPACE = 0x20;

/**
 * True when `repr()` emits this code point verbatim rather than as an escape.
 *
 * Note this is a *category* test, not an ASCII test: combining marks (Mn) and
 * astral digits (Nd) both print raw, while U+00AD and U+FEFF do not.
 */
export function isPrintable(codePoint) {
  if (codePoint === SPACE) return true;
  return !NON_PRINTABLE.test(String.fromCodePoint(codePoint));
}

const DECIMAL_DIGIT = /\p{Nd}/u;

/** True when the code point carries General_Category=Nd. */
export function isDecimalDigit(codePoint) {
  return DECIMAL_DIGIT.test(String.fromCodePoint(codePoint));
}

/**
 * Numeric value 0-9 of an Nd code point, or -1 when it is not Nd.
 *
 * Nd assignments come in aligned runs of ten, so the value is the distance back
 * to the start of the enclosing run. Runs can abut — U+1D7CE..U+1D7FF packs
 * five ten-digit alphabets contiguously — but because every run is ten long and
 * ten-aligned, taking the distance modulo ten stays exact. (Verified: U+1D7DD,
 * DOUBLE-STRUCK FIVE, sits 15 code points into that block and resolves to 5.)
 */
export function decimalValue(codePoint) {
  if (!isDecimalDigit(codePoint)) return -1;
  let distance = 0;
  // Walk back to the first non-Nd code point; the run start is one past it.
  while (isDecimalDigit(codePoint - distance - 1)) {
    distance += 1;
    // Guard against pathological runs so this can never spin unbounded.
    if (distance > 1000) return -1;
  }
  return distance % 10;
}

