/**
 * CPython's `repr()` and `str()` for the value types this program prints.
 *
 * `print(b)` goes through `repr()` for the keys and values inside the mapping,
 * while `print(b[k])` goes through `str()`. The two differ: a key containing an
 * apostrophe prints raw on its own line but quoted-and-escaped inside the
 * mapping, so both spellings are needed.
 */

import { isPrintable } from './unicode.mjs';

const BACKSLASH = 0x5c;
const TAB = 0x09;
const NEWLINE = 0x0a;
const CARRIAGE_RETURN = 0x0d;
const SINGLE_QUOTE = 0x27;
const DOUBLE_QUOTE = 0x22;

/** Lowercase hex, zero-padded to `width` — matching CPython's escape spelling. */
function hex(codePoint, width) {
  return codePoint.toString(16).padStart(width, '0');
}

/**
 * `repr()` of a Python `str`.
 *
 * Quote selection follows CPython: single quotes by default, switching to double
 * quotes only when the string contains a single quote and no double quote. When
 * it contains both, single quotes are kept and the apostrophes are escaped.
 *
 * Escapes are `\\`, `\t`, `\n`, `\r`, the active quote, and then by width for
 * anything non-printable: `\xNN` below U+0100, `\uNNNN` below U+10000, and
 * `\UNNNNNNNN` above. Printable non-ASCII (including combining marks and
 * astral digits) is emitted verbatim.
 */
export function reprStr(value) {
  const quote = value.includes("'") && !value.includes('"')
    ? DOUBLE_QUOTE
    : SINGLE_QUOTE;

  let out = String.fromCharCode(quote);
  // Iterating the string yields whole code points, so astral characters are
  // classified and escaped as one unit rather than as surrogate halves.
  for (const character of value) {
    const codePoint = character.codePointAt(0);
    if (codePoint === quote || codePoint === BACKSLASH) {
      out += '\\' + character;
    } else if (codePoint === TAB) {
      out += '\\t';
    } else if (codePoint === NEWLINE) {
      out += '\\n';
    } else if (codePoint === CARRIAGE_RETURN) {
      out += '\\r';
    } else if (isPrintable(codePoint)) {
      out += character;
    } else if (codePoint < 0x100) {
      out += '\\x' + hex(codePoint, 2);
    } else if (codePoint < 0x10000) {
      out += '\\u' + hex(codePoint, 4);
    } else {
      out += '\\U' + hex(codePoint, 8);
    }
  }
  return out + String.fromCharCode(quote);
}

/**
 * `repr()`/`str()` of a Python `int`.
 *
 * Values are carried as BigInt so that arbitrary-precision inputs survive: the
 * reference build round-trips 9007199254740993 and 26-digit literals exactly,
 * which a double could not.
 */
export function reprInt(value) {
  return value.toString();
}

/** `repr()` of a Python tuple, e.g. `("it's", 999)`. */
export function reprTuple(items) {
  if (items.length === 1) return `(${pyRepr(items[0])},)`;
  return `(${items.map(pyRepr).join(', ')})`;
}

/** Dispatching `repr()` for the value types that reach it here. */
export function pyRepr(value) {
  if (typeof value === 'string') return reprStr(value);
  if (typeof value === 'bigint') return reprInt(value);
  if (Array.isArray(value)) return reprTuple(value);
  return String(value);
}

/**
 * Dispatching `str()`.
 *
 * For `str` this is the identity — the raw characters, no quotes and no
 * escaping — which is why `print(b.inv[v])` shows an apostrophe bare.
 */
export function pyStr(value) {
  if (typeof value === 'string') return value;
  if (typeof value === 'bigint') return reprInt(value);
  if (Array.isArray(value)) return reprTuple(value);
  return String(value);
}

