/**
 * CPython's `int(str)` coercion, which is what `argparse`'s `type=int` invokes.
 *
 * This is considerably more permissive than JavaScript's `Number()`/`parseInt()`
 * and the differences are all observable through the reference build:
 *   - Unicode whitespace is stripped from both ends (U+3000 and U+0085 count,
 *     U+FEFF and U+200B do not).
 *   - Any General_Category=Nd digit is accepted, so `٥`, `९`, `５` and even
 *     U+1D7DD all parse; `²` (No) and `Ⅴ` (Nl) do not.
 *   - Underscores may separate digits but may not lead, trail, or repeat.
 *   - There is no bound on magnitude, hence BigInt.
 * Rejected by design: `0x10`, `0b11`, `5.0`, `1e5`, `inf`, `nan`, and a sign
 * separated from its digits by a space.
 */

import { isIntWhitespace, isDecimalDigit, decimalValue } from './unicode.mjs';

const UNDERSCORE = 0x5f;
const PLUS = 0x2b;
const MINUS = 0x2d;

/** Raised when the text is not a valid Python integer literal. */
export class PyValueError extends Error {}

/**
 * Parse `text` the way `int()` would and return a BigInt.
 *
 * @throws {PyValueError} when `int()` would raise `ValueError`.
 */
export function pyInt(text) {
  const codePoints = Array.from(text, (character) => character.codePointAt(0));

  let start = 0;
  let end = codePoints.length;
  while (start < end && isIntWhitespace(codePoints[start])) start += 1;
  while (end > start && isIntWhitespace(codePoints[end - 1])) end -= 1;

  let negative = false;
  if (start < end && (codePoints[start] === PLUS || codePoints[start] === MINUS)) {
    negative = codePoints[start] === MINUS;
    start += 1;
  }

  // A bare sign, or nothing at all, is a ValueError.
  if (start >= end) throw new PyValueError();

  // Accumulate in base 10 over BigInt so magnitude is unbounded. Digits are
  // normalised through their Nd value, which is how a Devanagari nine and an
  // ASCII nine end up equal.
  let magnitude = 0n;
  let previousWasUnderscore = true; // a leading underscore is invalid
  for (let index = start; index < end; index += 1) {
    const codePoint = codePoints[index];
    if (codePoint === UNDERSCORE) {
      // Underscores must sit strictly between digits: no leading, no doubling.
      if (previousWasUnderscore) throw new PyValueError();
      previousWasUnderscore = true;
      continue;
    }
    if (!isDecimalDigit(codePoint)) throw new PyValueError();
    magnitude = magnitude * 10n + BigInt(decimalValue(codePoint));
    previousWasUnderscore = false;
  }
  // A trailing underscore leaves the flag set.
  if (previousWasUnderscore) throw new PyValueError();

  return negative ? -magnitude : magnitude;
}

