/**
 * Byte-exact, synchronous stdout/stderr.
 *
 * `process.stdout.write` buffers asynchronously when stdout is a pipe, which
 * both reorders output against stderr and risks losing the tail on a non-zero
 * exit. The reference build flushes stdout before its traceback reaches stderr
 * even under a pipe, so writes go straight to the file descriptors here.
 */

import { writeSync } from 'node:fs';

const STDOUT = 1;
const STDERR = 2;

/**
 * Write a UTF-8 buffer to `fd`, retrying on the transient errors a non-blocking
