/**
 * Insertion-ordered paired storage: the substrate the bidirectional mapping is
 * built on.
 *
 * Two lookup indexes are maintained side by side — key to slot and value to slot
 * — over a single ordered array of slots, so a forward lookup, a reverse lookup,
 * and ordered iteration are all available without re-deriving anything.
 *
 * The indexes are null-prototype objects rather than any built-in associative
 * container, and every property name is prefixed with U+0000. Keys arrive
 * straight from the command line, so names like `__proto__`, `constructor` and
 * `hasOwnProperty` are all reachable input; a null prototype plus a prefix that
 * cannot occur in a shell argument keeps them ordinary data.
 *
 * Values are BigInt and are indexed by their decimal spelling, which is
 * canonical and injective for BigInt (there is no `-0`, and no two distinct
 * BigInts share a `toString`).
 */

const PREFIX = '�';

/** Fresh, prototype-less index object. */
function newIndex() {
  return Object.create(null);
}

/** Property name for a string key. */
function keyName(key) {
  return PREFIX + key;
}

/** Property name for a BigInt value. */
function valueName(value) {
  return PREFIX + value.toString();
}

export class PairedStore {
  constructor() {
    /** Live slots in insertion order; each is `{ key, value }`. */
    this._slots = [];
    this._byKey = newIndex();
    this._byValue = newIndex();
  }

  /** Number of entries. */
  get size() {
    return this._slots.length;
  }

  /** Slots in insertion order. Callers must not mutate the result. */
  entries() {
    return this._slots;
  }

  /** The slot holding `key`, or undefined. */
  slotForKey(key) {
    return this._byKey[keyName(key)];
  }

  /** The slot holding `value`, or undefined. */
  slotForValue(value) {
    return this._byValue[valueName(value)];
  }

  /**
   * Append a new entry. The caller has already established that neither the key
   * nor the value is present.
   */
  append(key, value) {
    const slot = { key, value };
    this._slots.push(slot);
    this._byKey[keyName(key)] = slot;
    this._byValue[valueName(value)] = slot;
  }

  /**
   * Retarget an existing slot at a new value, dropping the old value from the
   * reverse index.
   *
   * The slot is edited in place, so the key holds its original position in the
   * ordering — this is what makes a re-assigned first key still print first.
   */
  retarget(slot, value) {
    delete this._byValue[valueName(slot.value)];
    slot.value = value;
    this._byValue[valueName(value)] = slot;
  }
}

