/**
 * The bidirectional mapping itself.
 *
 * Only the surface `test8` exercises is modelled: `b[k] = v`, `b[k]`, `b.inv[v]`,
 * and `repr(b)`. The interesting part is the assignment policy, recovered from
 * the reference build rather than from source.
 *
 * `__setitem__` applies "drop the old entry on a duplicate key, raise on a
 * duplicate value":
 *
 *   key present | value present | same entry | outcome
 *   ------------|---------------|------------|----------------------------------
 *   no          | no            | -          | append a new entry
 *   yes         | no            | -          | retarget in place, keep position
 *   no          | yes           | -          | ValueDuplicationError(value)
 *   yes         | yes           | yes        | no-op
 *   yes         | yes           | no         | KeyAndValueDuplicationError(k, v)
 *
 * `KeyDuplicationError` is unreachable through assignment precisely because the
 * key policy is "drop old" rather than "raise"; it exists in the error module
 * for completeness only.
 */

import { PairedStore } from './store.mjs';
import { ValueDuplicationError, KeyAndValueDuplicationError } from './errors.mjs';
import { PyKeyError } from '../python/exceptions.mjs';
import { reprStr, reprInt } from '../python/repr.mjs';

/**
 * The `.inv` view: the same entries, addressed value-first.
 *
 * It reads through to the owning bidict's store rather than keeping a copy, so
 * it can never drift out of step with the forward direction.
 */
class InverseView {
  constructor(store) {
    this._store = store;
  }

  /** `b.inv[value]` — the key mapped to `value`. */
  get(value) {
    const slot = this._store.slotForValue(value);
    if (slot === undefined) throw new PyKeyError(value);
    return slot.key;
  }

  /** `repr(b.inv)`, with the pairs reversed. */
  toString() {
    const body = this._store
      .entries()
      .map((slot) => `${reprInt(slot.value)}: ${reprStr(slot.key)}`)
      .join(', ');
    return `bidict({${body}})`;
  }
}

export class Bidict {
  constructor() {
    this._store = new PairedStore();
    this.inv = new InverseView(this._store);
  }

  /** `b[key] = value`, applying the policy table above. */
  set(key, value) {
    const keySlot = this._store.slotForKey(key);
    const valueSlot = this._store.slotForValue(value);

    if (keySlot !== undefined && valueSlot !== undefined) {
      // Both halves already exist. Harmless when they are the very same entry —
      // re-asserting a pair changes nothing — and a conflict otherwise.
      if (keySlot === valueSlot) return;
      throw new KeyAndValueDuplicationError(key, value);
    }
    if (valueSlot !== undefined) {
      // A new key trying to claim a value another key holds.
      throw new ValueDuplicationError(value);
    }
    if (keySlot !== undefined) {
      this._store.retarget(keySlot, value);
      return;
    }
    this._store.append(key, value);
  }

  /** `b[key]` — the value mapped to `key`. */
  get(key) {
    const slot = this._store.slotForKey(key);
    if (slot === undefined) throw new PyKeyError(key);
    return slot.value;
  }

  /**
   * `repr(b)` — `bidict({'a': 1, 'b': 2})`, in insertion order.
   *
   * Keys go through `repr()` and so are quoted and escaped; values are plain
   * decimal. An empty mapping collapses to `bidict()`, not `bidict({})`.
   */
  toString() {
    if (this._store.size === 0) return 'bidict()';
    const body = this._store
      .entries()
      .map((slot) => `${reprStr(slot.key)}: ${reprInt(slot.value)}`)
      .join(', ');
    return `bidict({${body}})`;
  }
}

/** Factory mirroring the `bidict()` call in the Python source. */
export function bidict() {
  return new Bidict();
}

