/**
 * `argparse.ArgumentError` — a problem attributable to one argument.
 *
 * Rendered as `argument --v1: invalid int value: 'x'` when an argument owns the
 * failure, or as the bare message when it does not (the ambiguous-option case
 * raises with no owning argument, which is why that message has no prefix).
 */
export class ArgumentError extends Error {
  constructor(argumentName, message) {
    super(message);
    this.argumentName = argumentName;
    this.rawMessage = message;
