/**
 * Terminal-width discovery, mirroring `shutil.get_terminal_size()`.
 *
 * This matters because `argparse` lays usage and help out against the terminal
 * width, so the reference build's output genuinely changes with `COLUMNS`:
 * at `COLUMNS=78` the usage line is one line, at 77 it wraps.
 */

/**
 * Resolve the column count.
 *
 * `COLUMNS` wins when it parses as a positive integer — a non-numeric or
 * non-positive value is discarded rather than honoured (verified: `COLUMNS=abc`
 * and `COLUMNS=0` both fall through). Failing that, the real terminal width is
 * used when stdout is a tty, and 80 otherwise, which is the case that applies
 * whenever output is piped.
 */
export function terminalColumns(env = process.env, stream = process.stdout) {
  const declared = Number.parseInt(env.COLUMNS ?? '', 10);
  if (Number.isInteger(declared) && declared > 0) return declared;
  if (stream && stream.isTTY && stream.columns > 0) return stream.columns;
  return 80;
}

