/**
 * `argparse.HelpFormatter` — usage-line and help-text layout.
 *
 * The layout constants are not cosmetic: every one of them is observable. The
 * wrapping below reproduces the reference build at COLUMNS 1, 20, 30, 32, 33,
 * 76, 77, 78 and the default 80.
 */

import { terminalColumns } from './terminal.mjs';

const PREFIX = 'usage: ';
const INDENT = 2;

/**
 * Split a rendered usage fragment into the units wrapping may not break.
 *
 * `argparse` uses this regex, and its consequences are visible: a bracketed
 * group like `[-h]` stays whole, but `--k1 K1` is *two* units, so a narrow
 * terminal really does separate an option from its metavar.
 */
const USAGE_PART = /\(.*?\)+(?=\s|$)|\[.*?\]+(?=\s|$)|\S+/g;

/**
 * Greedy wrap of usage parts.
 *
 * Reproduces `argparse`'s `get_lines`: the running length starts one short of
 * the indent so the first part never pays for a leading space, and a part that
 * cannot fit is still emitted alone rather than dropped — which is what keeps
 * output sane at COLUMNS=1.
 */
function wrapParts(parts, indent, textWidth, firstPrefix) {
  const lines = [];
  let line = [];
  let lineLength = (firstPrefix === undefined ? indent.length : firstPrefix.length) - 1;
  for (const part of parts) {
    if (lineLength + 1 + part.length > textWidth && line.length > 0) {
      lines.push(indent + line.join(' '));
      line = [];
      lineLength = indent.length - 1;
    }
    line.push(part);
    lineLength += 1 + part.length;
  }
  if (line.length > 0) lines.push(indent + line.join(' '));
  if (firstPrefix !== undefined && lines.length > 0) {
    lines[0] = lines[0].slice(indent.length);
  }
  return lines;
}

/** Greedy word wrap of a plain help string, as `textwrap.wrap` would. */
function wrapText(text, width) {
  const words = text.split(/\s+/).filter(Boolean);
  const lines = [];
  let line = '';
  for (const word of words) {
    if (line === '') {
      line = word;
    } else if (line.length + 1 + word.length <= width) {
      line += ' ' + word;
    } else {
      lines.push(line);
      line = word;
    }
  }
  if (line !== '') lines.push(line);
  return lines.length > 0 ? lines : [''];
}

export class HelpFormatter {
  constructor(prog, columns = terminalColumns()) {
    this.prog = prog;
