 * A source map of the original `test8.py`.
 *
 * When the reference build dies, its traceback quotes the Python line that
 * failed and underlines the failing subexpression. Reproducing that means
 * keeping the original text, its line number, and its marker line — none of
 * which are recoverable from the JavaScript port at runtime.
 *
 * Markers follow CPython's fine-grained scheme: `~` under the object being
 * subscripted and `^` under the subscript itself.
 */

/** Statements in `test8.py` that can raise, keyed by a symbolic name. */
export const CALL_SITES = Object.freeze({
  // b[args.k1] = args.v1 — cannot fail: the mapping is empty, so neither the
  // key nor the value can already be present. Retained for completeness.
  setK1: { line: 15, source: 'b[args.k1] = args.v1', marker: '~^^^^^^^^^', markerIndent: 4 },
  setK2: { line: 16, source: 'b[args.k2] = args.v2', marker: '~^^^^^^^^^', markerIndent: 4 },
  setK3: { line: 17, source: 'b[args.k3] = args.v3', marker: '~^^^^^^^^^', markerIndent: 4 },
  // print(b[args.k1]) — also unreachable: k1 is inserted first and a later
  // duplicate key only retargets it, so it is never removed.
  getK1: { line: 21, source: 'print(b[args.k1])', marker: '~^^^^^^^^^', markerIndent: 10 },
  invV2: { line: 22, source: 'print(b.inv[args.v2])', marker: '~~~~~^^^^^^^^^', markerIndent: 10 },
  invV3: { line: 23, source: 'print(b.inv[args.v3])', marker: '~~~~~^^^^^^^^^', markerIndent: 10 },
  setUpdate: { line: 26, source: 'b[args.k1] = 999', marker: '~^^^^^^^^^', markerIndent: 4 },
});

