/**
 * Node.js port of `test8.py`.
 *
 * Mirrors the original statement for statement so the mapping between the two is
 * obvious, and so the `siteName` passed to the traceback reporter can name the
 * exact Python line each operation corresponds to.
 *
 *   import argparse
 *   from bidict import bidict
 *   ...
 *   b = bidict()
 *   b[args.k1] = args.v1
 *   ...
 */

import { ArgumentParser } from './lib/argparse/parser.mjs';
import { SystemExit } from './lib/argparse/errors.mjs';
import { bidict } from './lib/bidict/bidict.mjs';
import { pyInt } from './lib/python/int.mjs';
import { printLine } from './lib/python/stdio.mjs';
import { pyStr } from './lib/python/repr.mjs';
import { reportFatal } from './lib/runtime/traceback.mjs';

/** `type=str` — argparse hands the argument through untouched. */
const str = (text) => text;
str.pyName = 'str';

/** `type=int` — CPython's `int()`, reported as "int" in error messages. */
const int = (text) => pyInt(text);
int.pyName = 'int';

function main(argv) {
  const parser = new ArgumentParser();
  parser.addArgument('--k1', { type: str, required: true });
  parser.addArgument('--v1', { type: int, required: true });
  parser.addArgument('--k2', { type: str, required: true });
  parser.addArgument('--v2', { type: int, required: true });
  parser.addArgument('--k3', { type: str, required: true });
  parser.addArgument('--v3', { type: int, required: true });
  const args = parser.parseArgs(argv);

  // 复杂的多步操作
  const b = bidict();
  // Each assignment is wrapped so a duplication failure can be attributed to the
  // Python line it came from; the reference traceback names that line.
  try {
    b.set(args.k1, args.v1);
  } catch (error) {
    return reportFatal(error, 'setK1');
  }
  try {
    b.set(args.k2, args.v2);
  } catch (error) {
    return reportFatal(error, 'setK2');
  }
  try {
    b.set(args.k3, args.v3);
  } catch (error) {
    return reportFatal(error, 'setK3');
  }
  printLine(b.toString());

  // 通过不同方式访问
  try {
    printLine(pyStr(b.get(args.k1)));
  } catch (error) {
    return reportFatal(error, 'getK1');
  }
  try {
    printLine(pyStr(b.inv.get(args.v2)));
  } catch (error) {
    return reportFatal(error, 'invV2');
  }
  try {
    printLine(pyStr(b.inv.get(args.v3)));
  } catch (error) {
    return reportFatal(error, 'invV3');
  }

  // 更新一个值
  try {
    b.set(args.k1, 999n);
  } catch (error) {
    return reportFatal(error, 'setUpdate');
  }
  printLine(b.toString());

  return 0;
}

try {
  // process.argv is [node, script, ...args]; Python's sys.argv[1:] is the tail.
  process.exitCode = main(process.argv.slice(2));
} catch (error) {
  if (error instanceof SystemExit) {
    process.exitCode = error.status;
  } else {
    throw error;
  }
}

