/**
 * A stand-in for CPython's `linecache`, which is what puts the quoted source
 * line into a traceback.
 *
 * This is load-bearing for output fidelity in a way that is easy to miss: the
 * reference build's traceback includes the offending Python line *only when a
 * file named `test8.py` happens to be readable in the current directory*, since
 * the frozen binary carries no source. Run it from the directory holding the
 * original script and the traceback is five lines; run it from anywhere else and
 * the same failure prints three. Both are reproduced here.
 */

import { readFileSync } from 'node:fs';

/** Cached lines of `test8.py`, or null when it could not be read. */
let cache;

/**
 * Lines of `test8.py` resolved against the current directory, each keeping its
 * trailing newline.
 *
 * Line endings are normalised because Python reads source in text mode, where
 * universal newlines turn `\r\n` into `\n` before any offset arithmetic.
 */
function load() {
  if (cache !== undefined) return cache;
  try {
    const text = readFileSync('test8.py', 'utf8').replace(/\r\n?/g, '\n');
    // Keep the newline on each line, as linecache does.
    cache = text.split(/(?<=\n)/);
  } catch {
    cache = null;
  }
  return cache;
}

/**
 * The raw text of line `lineNumber` (1-based) including its trailing newline, or
 * null when the file or the line is unavailable.
 */
export function getLine(lineNumber) {
  const lines = load();
  if (lines === null || lineNumber < 1 || lineNumber > lines.length) return null;
  return lines[lineNumber - 1];
}

/** Reset the cache. Exposed for tests. */
export function invalidate() {
  cache = undefined;
}

