input.content:
/**
 * A source map of the original `test8.py`.
 *
 * When the reference build dies, its traceback quotes the failing Python line and
 * underlines the failing subexpression. Neither the line text nor the column
 * span is recoverable from the JavaScript port at runtime, so both are recorded
 * here alongside the line number.
 *
 * `colOffset`/`endColOffset` are the byte offsets the CPython code object carries
 * for the subexpression that raised — the subscript `b[args.k2]` or
 * `b.inv[args.v2]`, not the whole statement. `tildes` splits the underline the
 * way CPython's fine-grained anchors do: `~` beneath the object being
 * subscripted, `^` beneath the subscript.
 */

/** Statements in `test8.py` that can raise, keyed by a symbolic name. */
export const CALL_SITES = Object.freeze({
  // b[args.k1] = args.v1 — cannot fail: the mapping is still empty, so neither
  // the key nor the value can already be present. Recorded for completeness.
  setK1: { line: 15, source: 'b[args.k1] = args.v1', colOffset: 0, endColOffset: 10, tildes: 1 },
  setK2: { line: 16, source: 'b[args.k2] = args.v2', colOffset: 0, endColOffset: 10, tildes: 1 },
  setK3: { line: 17, source: 'b[args.k3] = args.v3', colOffset: 0, endColOffset: 10, tildes: 1 },
  // print(b[args.k1]) — also unreachable: k1 is inserted first, and a later
  // duplicate key only retargets it, so it is never removed.
  getK1: { line: 21, source: 'print(b[args.k1])', colOffset: 6, endColOffset: 16, tildes: 1 },
  invV2: { line: 22, source: 'print(b.inv[args.v2])', colOffset: 6, endColOffset: 20, tildes: 5 },
  invV3: { line: 23, source: 'print(b.inv[args.v3])', colOffset: 6, endColOffset: 20, tildes: 5 },
  setUpdate: { line: 26, source: 'b[args.k1] = 999', colOffset: 0, endColOffset: 10, tildes: 1 },
});

/**
 * The library frames that appear below the `test8.py` frame.
 *
 * `bidict` raises from two different places inside `_dedup`, and the line number
 * is what distinguishes them: 347 when only the value collides, 333 when the key
 * and the value both do.
 */
const SETITEM_FRAMES = [
  { file: 'bidict/_bidict.py', line: 80, name: '__setitem__' },
  { file: 'bidict/_bidict.py', line: 106, name: 'put' },
  { file: 'bidict/_base.py', line: 454, name: '_update' },
];

/** Frame chain for a duplicate-value assignment. */
export const VALUE_DUPLICATION_FRAMES = [
  ...SETITEM_FRAMES,
  { file: 'bidict/_base.py', line: 347, name: '_dedup' },
];

/** Frame chain for a simultaneous key-and-value duplication. */
export const KEY_AND_VALUE_DUPLICATION_FRAMES = [
  ...SETITEM_FRAMES,
  { file: 'bidict/_base.py', line: 333, name: '_dedup' },
];

/** Frame chain for a failed lookup through the inverse view. */
export const LOOKUP_FRAMES = [
  { file: 'bidict/_base.py', line: 524, name: '__getitem__' },
];

