input.content:
/**
 * Renders a CPython traceback plus the PyInstaller trailer, so a failing run of
 * the port produces the same stderr as a failing run of the reference build.
 *
 * One field cannot be matched: the number in `[PYI-NNN:ERROR]` is the reporting
 * process's pid, so it differs between any two runs — including two runs of the
 * reference build itself. `process.pid` is used, which reproduces the shape and
 * the variability rather than a constant that would always be wrong.
 */

import { writeStderr } from '../python/stdio.mjs';
import {
  CALL_SITES,
  VALUE_DUPLICATION_FRAMES,
  KEY_AND_VALUE_DUPLICATION_FRAMES,
  LOOKUP_FRAMES,
} from './callsites.mjs';
import { getLine } from './linecache.mjs';
import { PyKeyError } from '../python/exceptions.mjs';
import { ValueDuplicationError, KeyAndValueDuplicationError } from '../bidict/errors.mjs';

/** Name PyInstaller reports for the frozen script. */
const SCRIPT_NAME = 'test8';

/** Indent CPython puts before a quoted source line. */
const QUOTE_INDENT = 4;

/** Pick the library frames that belong under a given exception. */
function framesFor(error) {
  if (error instanceof ValueDuplicationError) return VALUE_DUPLICATION_FRAMES;
  if (error instanceof KeyAndValueDuplicationError) return KEY_AND_VALUE_DUPLICATION_FRAMES;
  if (error instanceof PyKeyError) return LOOKUP_FRAMES;
  return [];
}

/** Code points, not UTF-16 units — Python measures strings in code points. */
function codePointLength(text) {
  let count = 0;
  for (const _ of text) count += 1;
  return count;
}

/**
 * CPython's `_byte_offset_to_character_offset`.
 *
 * Column offsets in a code object are byte offsets into the UTF-8 source, so they
 * must be converted before they can index the decoded line. The conversion also
 * clips: an offset past the end of the line yields the line's own length, which
 * is what keeps the underline inside a line shorter than the original.
 */
function byteOffsetToCharOffset(line, byteOffset) {
  const bytes = Buffer.from(line, 'utf8');
  if (byteOffset >= bytes.length) return codePointLength(line);
  return codePointLength(bytes.subarray(0, byteOffset).toString('utf8'));
}

/**
 * Build the `File "test8.py", ...` frame, with the quoted line and underline when
 * the source is available.
 */
function formatScriptFrame(site) {
  const header = `  File "test8.py", line ${site.line}, in <module>`;
  const raw = getLine(site.line);
  if (raw === null) return [header];

  const stripped = raw.trim();
  if (stripped === '') return [header];

  // CPython measures how much the strip removed so the underline can be shifted
  // to line up with the *stripped* text it prints.
  const strippedCharacters = codePointLength(raw) - codePointLength(stripped);
  const startOffset = byteOffsetToCharOffset(raw, site.colOffset) + 1;
  const endOffset = byteOffsetToCharOffset(raw, site.endColOffset) + 1;

  const leading = startOffset - strippedCharacters;
  const span = endOffset - startOffset;

  const lines = [header, `${' '.repeat(QUOTE_INDENT)}${stripped}`];

  // An underline spanning the entire quoted line tells the reader nothing, so
  // CPython omits it.
  if (leading === 0 && span === codePointLength(stripped)) return lines;

  // The `~`/`^` split comes from re-parsing the underlined segment. Rather than
  // re-implement a Python parser, the split is applied when the line still holds
  // the code it was recorded from; an unrelated line underlines uniformly, which
  // is what CPython does when the segment fails to parse.
  const marker = stripped === site.source
    ? '~'.repeat(site.tildes) + '^'.repeat(Math.max(span - site.tildes, 0))
    : '^'.repeat(Math.max(span, 0));

  lines.push(' '.repeat(QUOTE_INDENT + Math.max(leading, 0)) + marker);
  return lines;
}

/**
 * Build the traceback text for `error` raised at the named call site.
 *
 * @param {object} error A `PyException` carrying its own final line.
 * @param {string} siteName A key of {@link CALL_SITES}.
 */
export function formatTraceback(error, siteName) {
  const site = CALL_SITES[siteName];
  const lines = ['Traceback (most recent call last):', ...formatScriptFrame(site)];

  // Frozen builds ship no source for library modules, so these frames carry only
  // a location — never a quoted line.
  for (const frame of framesFor(error)) {
    lines.push(`  File "${frame.file}", line ${frame.line}, in ${frame.name}`);
  }

  lines.push(error.formatFinalLine());
  return lines.join('\n') + '\n';
}

/**
 * Emit the traceback and the PyInstaller trailer, then report the exit status the
 * reference build uses for an unhandled exception.
 *
 * @returns {number} The process exit status (always 1).
 */
export function reportFatal(error, siteName) {
  writeStderr(formatTraceback(error, siteName));
  writeStderr(
    `[PYI-${process.pid}:ERROR] Failed to execute script '${SCRIPT_NAME}' `
    + 'due to unhandled exception!\n',
  );
  return 1;
}

