// argv, byte-compare stdout/stderr/rc. The PyInstaller pid in the trailer is
// normalised since it varies between any two runs.
import { spawnSync } from 'node:child_process';

const EXE = '/workspace/dataset/test8_executable';
const PORT = ['/output/test8.mjs'];

const norm = (s) => s.replace(/\[PYI-\d+:ERROR\]/g, '[PYI-N:ERROR]');

function run(cmd, argv, args, env, cwd) {
  const r = spawnSync(cmd, [...argv, ...args], {
    encoding: 'buffer',
    env: { ...process.env, ...env },
    cwd,
    maxBuffer: 1 << 26,
  });
  return {
    out: r.stdout ? r.stdout.toString('utf8') : '',
    err: r.stderr ? r.stderr.toString('utf8') : '',
    rc: r.status,
  };
}

export function compare(args, env = {}, cwd = process.cwd()) {
  const a = run(EXE, [], args, env, cwd);
  const b = run('node', PORT, args, env, cwd);
  const ok = a.out === b.out && norm(a.err) === norm(b.err) && a.rc === b.rc;
  return { ok, args, env, cwd, ref: a, port: b };
}

function show(r) {
  const envStr = Object.keys(r.env).length ? `${JSON.stringify(r.env)} ` : '';
  console.log(`\n=== MISMATCH: ${envStr}${JSON.stringify(r.args)}`);
  for (const f of ['out', 'err']) {
    if (norm(r.ref[f]) !== norm(r.port[f])) {
      console.log(`--- ref.${f}  ${JSON.stringify(r.ref[f])}`);
      console.log(`--- port.${f} ${JSON.stringify(r.port[f])}`);
    }
  }
  if (r.ref.rc !== r.port.rc) console.log(`--- rc ref=${r.ref.rc} port=${r.port.rc}`);
}

export function runSuite(cases, CWD = process.cwd()) {
  let pass = 0;
  const fails = [];
  for (const c of cases) {
    const args = Array.isArray(c) ? c : c.args;
    const env = Array.isArray(c) ? {} : (c.env ?? {});
    const cwd = Array.isArray(c) ? CWD : (c.cwd ?? CWD);
    const r = compare(args, env, cwd);
    if (r.ok) pass += 1;
    else fails.push(r);
  }
  for (const f of fails) show(f);
  console.log(`\n${pass}/${cases.length} identical, ${fails.length} mismatched`);
  return fails.length;
}

