/**
 * A faithful-enough `argparse.ArgumentParser` for this program's fixed argument
 * set: six required value-taking long options plus the implicit `-h/--help`.
 *
 * Behaviours reproduced because they are observable in the reference build:
 *   - unique-prefix abbreviation (`--he` reaches `--help`), and the exact
 *     `ambiguous option: --k could match --k1, --k2, --k3` message, whose match
 *     list follows *declaration* order rather than sorted order;
 *   - `--opt=value`, including `--k1=` yielding the empty string;
 *   - `-` and `-1` accepted as values while `-x` is not, because `argparse`
 *     exempts negative-number-looking tokens only when no option resembles one;
 *   - `--` ending option parsing;
 *   - last occurrence of a repeated option winning;
 *   - error precedence: value conversion (eager, during the scan) before the
 *     missing-required check, which in turn precedes unrecognized-argument
 *     reporting.
 */

import { ArgumentError, SystemExit } from './errors.mjs';
import { HelpFormatter } from './formatter.mjs';
import { reprStr } from '../python/repr.mjs';
import { printLine, writeStderr } from '../python/stdio.mjs';

/**
 * `argparse._negative_number_matcher`.
 *
 * `\p{Nd}` rather than `\d`: the pattern is compiled against `str` in Python, so
 * its digit class is Unicode-aware and `-٥` counts as a negative number.
 */
const NEGATIVE_NUMBER = /^-[\p{Nd}]+$|^-[\p{Nd}]*\.[\p{Nd}]+$/u;

export class ArgumentParser {
  /**
   * @param {string} prog Program name used in usage and error lines. Python
   *   derives this from `basename(sys.argv[0])`; the reference build is invoked
   *   as `test8_executable`, so that name is the default here in order to keep
   *   stderr byte-identical.
   */
  constructor({ prog = 'test8_executable', columns } = {}) {
    this.prog = prog;
    this.columns = columns;
    this.actions = [];
    // Declaration-ordered option string -> action. A null prototype keeps
    // option strings from ever colliding with inherited property names.
    this._optionStrings = Object.create(null);
    this._optionOrder = [];

    this._addAction({
      optionStrings: ['-h', '--help'],
      dest: 'help',
      takesValue: false,
      required: false,
      help: 'show this help message and exit',
      isHelp: true,
    });
  }

  _addAction(action) {
    this.actions.push(action);
    for (const option of action.optionStrings) {
      this._optionStrings[option] = action;
      this._optionOrder.push(option);
    }
    return action;
  }

  /** `parser.add_argument('--k1', type=str, required=True)`. */
  addArgument(optionString, { type, required = false, help = '' } = {}) {
    const dest = optionString.replace(/^--?/, '').replace(/-/g, '_');
    return this._addAction({
      optionStrings: [optionString],
      dest,
      // The default metavar is the dest upper-cased: `--k1 K1`.
      metavar: dest.toUpperCase(),
      takesValue: true,
      type,
      required,
      help,
    });
  }

  _formatter() {
    return new HelpFormatter(this.prog, this.columns);
  }

  formatUsage() {
    return this._formatter().formatUsage(this.actions);
  }

  formatHelp() {
    return this._formatter().formatHelp(this.actions);
  }

  /** Print usage plus `prog: error: message` to stderr and exit 2. */
  error(message) {
    writeStderr(this.formatUsage());
    writeStderr(`${this.prog}: error: ${message}\n`);
    throw new SystemExit(2);
  }

  /**
   * The name `argparse` uses for an action in error messages: every option
   * string joined by `/`, so the help flag reports as `-h/--help` while a
   * single-spelling option like `--v1` reports as itself.
   */
  static _actionName(action) {
    return action.optionStrings.join('/');
  }

  /**
   * Classify one token.
   *
   * Returns null when the token is not an option at all, otherwise a triple of
   * `[action|null, optionString, explicitArg|null]`; a null action means the
   * token looks like an option but matches none.
   */
  _parseOptional(token) {
    if (token.length === 0) return null;
    if (token[0] !== '-') return null;
    if (token in this._optionStrings) return [this._optionStrings[token], token, null];
    // A lone '-' is a value, not an option.
    if (token.length === 1) return null;

    const equals = token.indexOf('=');
    if (equals !== -1) {
      const head = token.slice(0, equals);
      if (head in this._optionStrings) {
        return [this._optionStrings[head], head, token.slice(equals + 1)];
      }
    }

    const matches = this._optionTuples(token);
    if (matches.length > 1) {
      const names = matches.map(([, option]) => option).join(', ');
      throw new ArgumentError(null, `ambiguous option: ${token} could match ${names}`);
    }
    if (matches.length === 1) return matches[0];

    // No option matched. A negative-number-looking token is a value, since this
    // parser declares no option that could be confused for one.
    if (NEGATIVE_NUMBER.test(token)) return null;
    // Anything containing a space is a value too.
    if (token.includes(' ')) return null;

    return [null, token, null];
  }

  /** Unique-prefix candidates for an abbreviated option. */
  _optionTuples(token) {
    const results = [];
    if (token.startsWith('--')) {
      const equals = token.indexOf('=');
      const prefix = equals === -1 ? token : token.slice(0, equals);
      const explicit = equals === -1 ? null : token.slice(equals + 1);
      for (const option of this._optionOrder) {
